E('formula',x=150,y=520,w=1620,h=150,lines=[dict(s='Split Info ＝ − Σ (N(vⱼ)/N) log₂ (N(vⱼ)/N)',at=d,col='PUR'),dict(s='Gain Ratio ＝ 資訊增益 ÷ Split Info',at=e,col='PUR',cjk=True)],size=36,lh=62)
E('chips',y=730,items=[dict(s='(a) Gini：Δ 用 Gini 算',col='OK',at=[e,2]),dict(s='(b) 資訊增益：Δ 用 Entropy 算',col='A',at=[e,2.5]),dict(s='(c) Gain Ratio：資訊增益 ÷ Split Info',col='PUR',at=[e,3])],size=24)
